    [Theory]
    [MemberData(nameof(Cases))]
    public void StyleNumberingMatchesWordAndSdkWithoutMutatingSource(string name, string documentXml, string numberingXml, string stylesXml)
    {
        using var stream = new MemoryStream();
        using var doc = WordprocessingDocument.Create(stream, WordprocessingDocumentType.Document);
        var main = doc.AddMainDocumentPart();
        main.Document = new Document(documentXml);
        main.AddNewPart<NumberingDefinitionsPart>().Numbering = new Numbering(numberingXml);
        var stylesPart = main.AddNewPart<StyleDefinitionsPart>();
        stylesPart.Styles = new Styles(stylesXml);
        _ = stylesPart.Styles.Descendants().ToArray();
        var original = stylesPart.Styles.OuterXml;
        using var oracleStream = new MemoryStream();
        using (var copy = doc.Clone(oracleStream)) { }
        using (var zip = new ZipArchive(oracleStream, ZipArchiveMode.Update, true))
        {
            var path = stylesPart.Uri.OriginalString.TrimStart('/');
            zip.GetEntry(path)!.Delete();
            using var writer = new StreamWriter(zip.CreateEntry(path).Open());
            writer.Write(stylesXml);
        }
        oracleStream.Position = 0;
        using var oracle = WordprocessingDocument.Open(oracleStream, false, new OpenSettings
        {
            MarkupCompatibilityProcessSettings = new(MarkupCompatibilityProcessMode.ProcessAllParts, FileFormatVersions.Office2007)
        });
        DxpITextVisitor[] Visitors() => [new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreatePlainConfig()),
            new DxpMarkdownVisitor(DxpMarkdownVisitorConfig.CreateRichConfig()),
            new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreatePlainConfig()),
            new DxpHtmlVisitor(DxpHtmlVisitorConfig.CreateRichConfig()),
            new DxpPlainTextVisitor(DxpPlainTextVisitorConfig.CreateAcceptConfig())];
        foreach (var source in new[] { oracle, doc })
            foreach (var visitor in Visitors())
            {
                var output = DxpExport.ExportToString(source, visitor);
                if (visitor is DxpHtmlVisitor or DxpMarkdownVisitor) output = new HtmlParser().ParseDocument(output).Body!.TextContent;
                // Word's forward inherited association cancels Base's numPr.
                var expected = name == "basedon-wrapper" ? Array.Empty<string>() : new[] { "BEGIN7END", "BEGIN8END", "BEGIN9END" };
                Assert.Equal(expected, Regex.Matches(output, "BEGIN\\d+END").Select(m => m.Value));
                Assert.Equal(3, Regex.Matches(output, "Item[0-2]").Count);
            }
        Assert.Equal(original, stylesPart.Styles.OuterXml);
    }
